const signal = sse.signal(input.handle);
await new Promise((r) => setTimeout(r, 300));
await fetch(getConfig("E2E_SINK_URL") + "/ev?k=" + encodeURIComponent(input.k) + "&e=watching");
await new Promise((r) => { signal.addEventListener("abort", r); setTimeout(r, 2000); });
if (signal.aborted) { await fetch(getConfig("E2E_SINK_URL") + "/ev?k=" + encodeURIComponent(input.k) + "&e=signal"); }
await fetch(getConfig("E2E_SINK_URL") + "/hold?k=" + encodeURIComponent(input.k));
await sse.send(input.handle, "after");
await sse.close(input.handle);
